import { getDomNodePagePosition } from 'monaco-editor/esm/vs/base/browser/dom.js';
import { CodeActionController } from 'monaco-editor/esm/vs/editor/contrib/codeAction/browser/codeActionController.js';
import {
  CodeActionKind,
  CodeActionTriggerSource,
} from 'monaco-editor/esm/vs/editor/contrib/codeAction/common/types.js';
import { MarkerHoverParticipant } from 'monaco-editor/esm/vs/editor/contrib/hover/browser/markerHoverParticipant.js';
import { StandaloneServices } from 'monaco-editor/esm/vs/editor/standalone/browser/standaloneServices.js';
import {
  MarkerController,
  NextMarkerAction,
} from 'monaco-editor/esm/vs/editor/contrib/gotoError/browser/gotoError.js';
import { ActionList } from 'monaco-editor/esm/vs/platform/actionWidget/browser/actionList.js';
import { ICommandService } from 'monaco-editor/esm/vs/platform/commands/common/commands.js';
import { isLikelyMobileBrowser } from './mobile-eruda.ts';
import { logKhmerTime } from './helpers.ts';

const KHMER_BASE_LETTER_RE = /[\u1780-\u17B3]/u;
const MOBILE_TOUCH_QUICK_FIX_QUERY = '(hover: none) and (max-width: 1024px)';
const SPELLCHECK_CODE = 'open-lyric-spellcheck';
const ADD_TO_CUSTOM_DICTIONARY_COMMAND_ID =
  'open-lyric.add-to-custom-dictionary';
const TOUCH_ACTION_WIDGET_GRACE_PERIOD_MS = 3000;
const markerHoverCodeActionTrigger = {
  type: 1,
  filter: { include: CodeActionKind.QuickFix },
  triggerAction: CodeActionTriggerSource.QuickFixHover,
};
const mobileSelectionHoverDisposables = new WeakMap<
  object,
  {
    dispose: () => void;
  }
>();
const runtimeHost = globalThis as typeof globalThis & {
  __openLyricKhmerMarkerHoverPatchApplied?: boolean;
  __openLyricLastTouchInteractionTime?: number;
  __openLyricTouchActionWidgetPatchApplied?: boolean;
  __openLyricTouchActionWidgetTrackingBound?: boolean;
};

function getKhmerHoverTimingNow() {
  return typeof globalThis.performance?.now === 'function'
    ? globalThis.performance.now()
    : Date.now();
}

function logKhmerHoverTiming(label: string, startTime: number, details = '') {
  const durationMs = getKhmerHoverTimingNow() - startTime;
  logKhmerTime(
    console.info,
    `hover ${label}: ${durationMs.toFixed(1)}ms${details ? ` ${details}` : ''}`,
  );
  return durationMs;
}

function getMarkerWordCharacterCount(editor, marker) {
  return Array.from(getMarkerWord(editor, marker)).length;
}

function isCancellationError(error: unknown) {
  const name = error instanceof Error ? error.name : '';
  const message = error instanceof Error ? error.message : String(error || '');
  return name === 'Canceled' || /canceled/iu.test(message);
}

function getMarkerWord(
  editor: {
    getModel?: () => {
      getValueInRange: (range: {
        startLineNumber: number;
        startColumn: number;
        endLineNumber: number;
        endColumn: number;
      }) => string;
    } | null;
  },
  marker: {
    startLineNumber: number;
    startColumn: number;
    endLineNumber: number;
    endColumn: number;
  },
) {
  const model = editor?.getModel?.();
  if (!model) {
    return '';
  }

  return model.getValueInRange({
    endColumn: marker.endColumn,
    endLineNumber: marker.endLineNumber,
    startColumn: marker.startColumn,
    startLineNumber: marker.startLineNumber,
  });
}

function formatSpellcheckSuggestionDisplayText(suggestion) {
  return String(suggestion || '')
    .replace(/\u200B/g, ' ')
    .replace(/\u200C/g, '[ZWNJ]')
    .replace(/\u200D/g, '[ZWJ]');
}

function formatAddToCustomDictionaryLabel(word) {
  const displayText = formatSpellcheckSuggestionDisplayText(word);

  return displayText
    ? `Add "${displayText}" to Custom Dictionary`
    : 'Add to Custom Dictionary';
}

function getCustomDictionaryMarkerPayload(editor, marker) {
  if (!marker) {
    return null;
  }

  const languageCode = String(marker.origin || '')
    .trim()
    .toLowerCase();
  const word = getMarkerWord(editor, marker);

  if (!languageCode || !word) {
    return null;
  }

  return { languageCode, word };
}

async function executeAddToCustomDictionaryCommand(payload) {
  const commandService = StandaloneServices.get(ICommandService) as {
    executeCommand: (id: string, payload: unknown) => Promise<unknown>;
  };

  return commandService.executeCommand(
    ADD_TO_CUSTOM_DICTIONARY_COMMAND_ID,
    payload,
  );
}

function isKhmerSpellcheckMarker(
  editor: {
    getModel?: () => unknown;
  },
  marker: {
    code?: unknown;
    origin?: unknown;
    startLineNumber: number;
    startColumn: number;
    endLineNumber: number;
    endColumn: number;
  },
) {
  if (String(marker?.code) !== SPELLCHECK_CODE) {
    return false;
  }

  if (
    String(marker?.origin || '')
      .trim()
      .toLowerCase() === 'km'
  ) {
    return true;
  }

  return KHMER_BASE_LETTER_RE.test(getMarkerWord(editor, marker));
}

function isSpellcheckMarker(marker: { code?: unknown }) {
  return String(marker?.code) === SPELLCHECK_CODE;
}

function matchesMediaQuery(query: string) {
  return Boolean(globalThis.matchMedia?.(query).matches);
}

function isLikelyTouchQuickFixBrowser() {
  return (
    isLikelyMobileBrowser() || matchesMediaQuery(MOBILE_TOUCH_QUICK_FIX_QUERY)
  );
}

function recordTouchInteraction() {
  runtimeHost.__openLyricLastTouchInteractionTime = Date.now();
}

function hasRecentTouchInteraction() {
  const lastTouchInteractionTime = Number(
    runtimeHost.__openLyricLastTouchInteractionTime || 0,
  );

  return (
    Date.now() - lastTouchInteractionTime <= TOUCH_ACTION_WIDGET_GRACE_PERIOD_MS
  );
}

function shouldUseTouchSafeActionWidgetBehavior() {
  return hasRecentTouchInteraction() && isLikelyTouchQuickFixBrowser();
}

function bindTouchActionWidgetTracking() {
  if (runtimeHost.__openLyricTouchActionWidgetTrackingBound) {
    return;
  }

  document.addEventListener(
    'pointerdown',
    (event) => {
      if (event.pointerType === 'touch') {
        recordTouchInteraction();
      }
    },
    true,
  );
  document.addEventListener(
    'touchstart',
    () => {
      recordTouchInteraction();
    },
    {
      capture: true,
      passive: true,
    },
  );

  runtimeHost.__openLyricTouchActionWidgetTrackingBound = true;
}

function removeActionWidgetPointerBlock(listDomNode: HTMLElement) {
  const contextView = listDomNode.closest('.context-view.monaco-component');
  const pointerBlock = contextView?.querySelector('.context-view-pointerBlock');

  if (pointerBlock instanceof HTMLElement) {
    pointerBlock.remove();
  }
}

function layoutTouchSafeActionList(actionList: any, minWidth: number) {
  const allMenuItems = Array.isArray(actionList?._allMenuItems)
    ? actionList._allMenuItems
    : [];
  const numHeaders = allMenuItems.filter(
    (item) => item?.kind === 'header',
  ).length;
  const numSeparators = allMenuItems.filter(
    (item) => item?.kind === 'separator',
  ).length;
  const itemsHeight =
    allMenuItems.length * Number(actionList?._actionLineHeight || 0);
  const heightWithHeaders =
    itemsHeight +
    numHeaders * Number(actionList?._headerLineHeight || 0) -
    numHeaders * Number(actionList?._actionLineHeight || 0);
  const heightWithSeparators =
    heightWithHeaders +
    numSeparators * Number(actionList?._separatorLineHeight || 0) -
    numSeparators * Number(actionList?._actionLineHeight || 0);

  actionList?._list?.layout?.(heightWithSeparators);

  let maxWidth = minWidth;
  if (allMenuItems.length >= 50) {
    maxWidth = 380;
  } else {
    const ownerDocument = actionList?.domNode?.ownerDocument;
    const itemWidths = allMenuItems.map((_item, index) => {
      const elementId = actionList?._list?.getElementID?.(index);
      const menuItemElement =
        typeof elementId === 'string'
          ? ownerDocument?.getElementById(elementId)
          : null;

      if (menuItemElement instanceof HTMLElement) {
        menuItemElement.style.width = 'auto';
        const itemWidth = menuItemElement.getBoundingClientRect().width;
        menuItemElement.style.width = '';
        return itemWidth;
      }

      return 0;
    });

    maxWidth = Math.max(...itemWidths, minWidth);
  }

  const layoutWindow =
    actionList?.domNode?.ownerDocument?.defaultView || globalThis.window;
  const layoutContainer =
    actionList?._layoutService?.getContainer?.(layoutWindow);
  const maxViewportHeightRatio = 0.7;
  const containerHeight = Number(layoutContainer?.clientHeight || 0);
  const height = Math.min(
    heightWithSeparators,
    containerHeight * maxViewportHeightRatio,
  );

  actionList?._list?.layout?.(height, maxWidth);

  if (actionList?.domNode instanceof HTMLElement) {
    actionList.domNode.style.height = `${height}px`;
    removeActionWidgetPointerBlock(actionList.domNode);
  }

  return maxWidth;
}

function patchTouchSafeActionWidget() {
  if (runtimeHost.__openLyricTouchActionWidgetPatchApplied) {
    return;
  }

  const actionListPrototype = ActionList?.prototype as {
    layout?: (minWidth: number) => number;
  };

  if (typeof actionListPrototype?.layout !== 'function') {
    return;
  }

  bindTouchActionWidgetTracking();

  const originalLayout = actionListPrototype.layout;

  actionListPrototype.layout = function patchedActionListLayout(
    this: unknown,
    minWidth: number,
  ) {
    if (!shouldUseTouchSafeActionWidgetBehavior()) {
      return originalLayout.call(this, minWidth);
    }

    return layoutTouchSafeActionList(this, minWidth);
  };

  runtimeHost.__openLyricTouchActionWidgetPatchApplied = true;
}

function shouldAutoOpenMobileSpellcheckHover() {
  return isLikelyTouchQuickFixBrowser();
}

function getRangeStart(range) {
  if (typeof range?.getStartPosition === 'function') {
    return range.getStartPosition();
  }

  return {
    lineNumber: Number(range?.startLineNumber || 0),
    column: Number(range?.startColumn || 0),
  };
}

function getRangeEnd(range) {
  if (typeof range?.getEndPosition === 'function') {
    return range.getEndPosition();
  }

  return {
    lineNumber: Number(range?.endLineNumber || 0),
    column: Number(range?.endColumn || 0),
  };
}

function createRangeSnapshot(range) {
  const start = getRangeStart(range);
  const end = getRangeEnd(range);

  return {
    startLineNumber: Number(start?.lineNumber || 0),
    startColumn: Number(start?.column || 0),
    endLineNumber: Number(end?.lineNumber || 0),
    endColumn: Number(end?.column || 0),
  };
}

function isEmptyRange(range) {
  return (
    range.startLineNumber === range.endLineNumber &&
    range.startColumn === range.endColumn
  );
}

function createRangeKey(range) {
  return [
    range.startLineNumber,
    range.startColumn,
    range.endLineNumber,
    range.endColumn,
  ].join(':');
}

function getSelectedSpellcheckMarker(
  editor: {
    getModel?: () => { uri: unknown } | null;
  },
  selection,
) {
  const model = editor?.getModel?.();
  if (
    !model ||
    typeof globalThis.monaco?.editor?.getModelMarkers !== 'function'
  ) {
    return null;
  }

  const selectionRange = createRangeSnapshot(selection);
  if (isEmptyRange(selectionRange)) {
    return null;
  }

  return (
    globalThis.monaco.editor
      .getModelMarkers({
        owner: SPELLCHECK_CODE,
        resource: model.uri,
      })
      .find((marker) => {
        return (
          isSpellcheckMarker(marker) &&
          createRangeKey(marker) === createRangeKey(selectionRange)
        );
      }) || null
  );
}

function attachMobileSpellcheckMarkerHoverSelection(editor: {
  getAction?: (actionId: string) => {
    run?: () => Promise<void> | void;
  } | null;
  getSelection?: () => unknown;
  onDidChangeCursorSelection?: (
    listener: (event: { selection?: unknown }) => void,
  ) => { dispose?: () => void };
}) {
  if (!editor || typeof editor.onDidChangeCursorSelection !== 'function') {
    return {
      dispose() {},
    };
  }

  const existingDisposable = mobileSelectionHoverDisposables.get(editor);
  if (existingDisposable) {
    return existingDisposable;
  }

  let lastSelectionKey = '';
  let pendingTimer = 0;
  let disposed = false;

  const cancelPendingTimer = () => {
    if (!pendingTimer) {
      return;
    }

    globalThis.clearTimeout(pendingTimer);
    pendingTimer = 0;
  };

  const selectionDisposable = editor.onDidChangeCursorSelection((event) => {
    if (!shouldAutoOpenMobileSpellcheckHover()) {
      lastSelectionKey = '';
      cancelPendingTimer();
      return;
    }

    const marker = getSelectedSpellcheckMarker(editor, event?.selection);
    if (!marker) {
      lastSelectionKey = '';
      cancelPendingTimer();
      return;
    }

    const selectionKey = createRangeKey(marker);
    if (selectionKey === lastSelectionKey) {
      return;
    }

    lastSelectionKey = selectionKey;
    cancelPendingTimer();
    pendingTimer = globalThis.setTimeout(() => {
      pendingTimer = 0;

      if (disposed) {
        return;
      }

      const selectedMarker = getSelectedSpellcheckMarker(
        editor,
        editor.getSelection?.(),
      );
      if (!selectedMarker || createRangeKey(selectedMarker) !== selectionKey) {
        if (lastSelectionKey === selectionKey) {
          lastSelectionKey = '';
        }
        return;
      }

      const showHoverAction = editor.getAction?.('editor.action.showHover');
      if (!showHoverAction?.run) {
        return;
      }

      void Promise.resolve(showHoverAction.run()).catch((error) => {
        if (!isCancellationError(error)) {
          console.error(
            'Failed to open spellcheck hover from mobile selection.',
            error,
          );
        }
      });
    }, 0);
  });

  const attachedDisposable = {
    dispose() {
      disposed = true;
      cancelPendingTimer();
      selectionDisposable?.dispose?.();
      mobileSelectionHoverDisposables.delete(editor);
    },
  };

  mobileSelectionHoverDisposables.set(editor, attachedDisposable);
  return attachedDisposable;
}

function renderSpellcheckMarkerStatusbar(
  participant: {
    _editor: {
      focus?: () => void;
      getOption?: (optionId: number) => unknown;
    };
    getCodeActions?: (marker: unknown) => Promise<{
      dispose?: () => void;
      validActions?: unknown[];
    }>;
  },
  context,
  markerHover,
) {
  const marker = markerHover?.marker;

  if (
    marker?.severity === globalThis.monaco?.MarkerSeverity?.Error ||
    marker?.severity === globalThis.monaco?.MarkerSeverity?.Warning ||
    marker?.severity === globalThis.monaco?.MarkerSeverity?.Info
  ) {
    const markerController = MarkerController.get(participant._editor);
    if (markerController) {
      context.statusBar.addAction({
        label: 'View Problem',
        commandId: NextMarkerAction.ID,
        run: () => {
          context.hide();
          markerController.showAtMarker(marker);
          participant._editor.focus();
        },
      });
    }
  }

  if (!participant._editor?.getOption?.(104)) {
    if (isKhmerSpellcheckMarker(participant._editor, marker)) {
      context.statusBar.addAction({
        commandId: '',
        label: 'Try Khmer Segmentation',
        run: async () => {
          const actionStartTime = getKhmerHoverTimingNow();
          const characterCount = getMarkerWordCharacterCount(
            participant._editor,
            marker,
          );
          let applied = false;

          context.hide();

          try {
            const spellcheckModule = await import('./spellcheck.ts');
            applied = await spellcheckModule.applyKhmerSegmentationMarkerEdit(
              participant._editor,
              marker,
            );
          } finally {
            logKhmerHoverTiming(
              'segmentation action',
              actionStartTime,
              `chars=${characterCount} applied=${String(applied)}`,
            );
            participant._editor.focus();
          }
        },
      });
    }

    const customDictionaryPayload = getCustomDictionaryMarkerPayload(
      participant._editor,
      marker,
    );

    if (customDictionaryPayload) {
      context.statusBar.addAction({
        commandId: ADD_TO_CUSTOM_DICTIONARY_COMMAND_ID,
        label: formatAddToCustomDictionaryLabel(customDictionaryPayload.word),
        run: async () => {
          context.hide();

          try {
            await executeAddToCustomDictionaryCommand(customDictionaryPayload);
          } catch (error) {
            console.error(
              'Failed to add spellcheck word to the custom dictionary from marker hover.',
              error,
            );
          } finally {
            participant._editor.focus?.();
          }
        },
      });
    }

    context.statusBar.addAction({
      commandId: 'editor.action.quickFix',
      label: 'Quick Fix...',
      run: async (target?: HTMLElement) => {
        const shouldLogTiming = isKhmerSpellcheckMarker(
          participant._editor,
          marker,
        );
        const actionStartTime = shouldLogTiming ? getKhmerHoverTimingNow() : 0;
        const characterCount = shouldLogTiming
          ? getMarkerWordCharacterCount(participant._editor, marker)
          : 0;
        const codeActionsPromise = participant.getCodeActions?.(marker);
        if (!codeActionsPromise) {
          participant._editor.focus?.();
          return;
        }

        let actionCount = 0;
        let canceled = false;
        let showedCodeActions = false;

        try {
          const actions = await codeActionsPromise;
          actionCount = Array.isArray(actions?.validActions)
            ? actions.validActions.length
            : 0;

          if (!actions?.validActions?.length) {
            actions?.dispose?.();
            participant._editor.focus?.();
            return;
          }

          const targetPosition =
            target instanceof HTMLElement
              ? getDomNodePagePosition(target)
              : null;

          context.hide();
          CodeActionController.get(
            participant._editor as never,
          )?.showCodeActions(
            markerHoverCodeActionTrigger,
            actions as never,
            targetPosition
              ? {
                  x: targetPosition.left,
                  y: targetPosition.top,
                  width: targetPosition.width,
                  height: targetPosition.height,
                }
              : undefined,
          );
          showedCodeActions = true;
        } catch (error) {
          canceled = isCancellationError(error);

          if (!canceled) {
            console.error(
              'Failed to load spellcheck quick fixes from marker hover.',
              error,
            );
          }
        } finally {
          if (shouldLogTiming) {
            logKhmerHoverTiming(
              'quick fix action',
              actionStartTime,
              `chars=${characterCount} actions=${actionCount} showed=${String(showedCodeActions)} canceled=${String(canceled)}`,
            );
          }

          if (!showedCodeActions) {
            participant._editor.focus?.();
          }
        }
      },
    });
  }
}

function patchKhmerMarkerHoverAction() {
  if (runtimeHost.__openLyricKhmerMarkerHoverPatchApplied) {
    return;
  }

  const participantPrototype = MarkerHoverParticipant?.prototype as {
    _renderMarkerStatusbar?: (
      context: {
        hide: () => void;
        onContentsChanged: () => void;
        statusBar: {
          addAction: (actionOptions: {
            commandId: string;
            label: string;
            run: (target?: HTMLElement) => void | Promise<void>;
          }) => unknown;
          append: (element: HTMLElement) => HTMLElement;
        };
      },
      markerHover: {
        marker: {
          code?: unknown;
          origin?: unknown;
          startLineNumber: number;
          startColumn: number;
          endLineNumber: number;
          endColumn: number;
        };
      },
    ) => unknown;
  };

  if (typeof participantPrototype?._renderMarkerStatusbar !== 'function') {
    return;
  }

  const originalRenderMarkerStatusbar =
    participantPrototype._renderMarkerStatusbar;

  participantPrototype._renderMarkerStatusbar =
    function patchedRenderMarkerStatusbar(context, markerHover) {
      if (!isSpellcheckMarker(markerHover?.marker)) {
        return originalRenderMarkerStatusbar.call(this, context, markerHover);
      }

      renderSpellcheckMarkerStatusbar(this, context, markerHover);
      return undefined;
    };

  runtimeHost.__openLyricKhmerMarkerHoverPatchApplied = true;
}

patchTouchSafeActionWidget();
patchKhmerMarkerHoverAction();

export {
  attachMobileSpellcheckMarkerHoverSelection,
  patchKhmerMarkerHoverAction,
};
